import subprocess,difflib,re
files=["skills/live-spec-base/SKILL.md","skills/communicator/SKILL.md","skills/build-pipeline/SKILL.md"]
maps={}
for f in files:
    old=subprocess.run(["git","show","HEAD:"+f],capture_output=True,text=True).stdout.split("\n")
    new=open(f).read().split("\n")
    sm=difflib.SequenceMatcher(None,old,new,autojunk=False)
    m={}
    for tag,i1,i2,j1,j2 in sm.get_opcodes():
        if tag=="equal":
            for k in range(i2-i1): m[i1+k+1]=j1+k+1
    maps[f]=m
    print(f,"lines",len(old),"->",len(new))
arch=open("ARCHITECTURE.md").read().split("\n")
changes=0
for idx,line in enumerate(arch):
    def repl(mo):
        global changes
        f,ln=mo.group(1),int(mo.group(2))
        if f in maps and ln in maps[f] and maps[f][ln]!=ln:
            changes+=1
            return "`%s:%d`"%(f,maps[f][ln])
        return mo.group(0)
    arch[idx]=re.sub(r"`(skills/(?:live-spec-base|communicator|build-pipeline)/SKILL\.md):(\d+)`",repl,line)
open("ARCHITECTURE.md","w").write("\n".join(arch))
print("pins renumbered:",changes)
PY
